'use strict';
// Browse large, prompt-owned risk lists without mounting an input form for every point.
const rsBase={configPanel,awRiskEditor,modalContent,handleAction,closeModal};
function rsCategory(node){const parts=String(node.path||'').split('/').map(s=>s.trim()).filter(Boolean);if(parts.at(-1)===node.name)parts.pop();return parts.join(' / ')||'未分类';}
function rsWithin(node,path){const category=rsCategory(node);return path==='all'||category===path||category.startsWith(path+' / ');}
function rsCounts(nodes){const groups=new Map();for(const node of nodes){const parts=rsCategory(node).split(' / ');for(let i=1;i<=parts.length;i++){const key=parts.slice(0,i).join(' / ');let g=groups.get(key);if(!g){g={path:key,label:parts[i-1],parent:i===1?'all':parts.slice(0,i-1).join(' / '),total:0,selected:0};groups.set(key,g);}g.total++;if(node.selected)g.selected++;}}return [...groups.values()];}
function rsState(p){p.category??='all';p.query??='';p.view??=currentTask()?'selected':'all';p.page??=1;p.size??=20;p.expanded??=[];p.error??='';if(p.category!=='all'&&!rsCounts(p.nodes).some(g=>g.path===p.category))p.category='all';return p;}
function rsMatches(p){const q=p.query.trim().toLowerCase();return p.nodes.map((node,index)=>({node,index})).filter(({node})=>rsWithin(node,p.category)&&(p.view!=='selected'||node.selected)&&(!q||[node.name,node.path,node.description].join(' ').toLowerCase().includes(q)));}
function rsSelected(nodes){return nodes.reduce((n,r)=>n+(r.selected?1:0),0);}
function rsSummary(c,locked){
 const checked=new Set(c.checks),nodes=c.riskNodes.map(n=>({...n,selected:checked.has(n.name)})),selected=nodes.filter(n=>n.selected),groups=rsCounts(nodes).filter(g=>g.parent==='all'),chosen=groups.filter(g=>g.selected);
 return '<section class="rs-summary"><div class="rs-summary-heading"><h3>检查风险点</h3><span>共 '+nodes.length+' 个</span></div><div class="rs-selected-count">'+(locked?'本次检查':'已选')+' <strong>'+selected.length+'</strong> 个风险点</div>'+(chosen.length?'<div class="rs-category-summary">'+chosen.slice(0,3).map(g=>'<span title="'+E(g.path)+'">'+E(g.label)+' <b>'+g.selected+'</b></span>').join('')+(chosen.length>3?'<span>等 '+chosen.length+' 类</span>':'')+'</div>':'<p class="rs-summary-empty">'+(nodes.length?'请选择本次要核查的风险点。':'当前提示词未配置风险点，可添加检查项。')+'</p>')+B(locked?'查看本次风险点':'选择风险点','aw-risk-editor','w100 sm '+(locked?'':'soft'),'aria-label="'+(locked?'查看本次':'选择本次检查的')+'风险点"')+'</section>';
}
configPanel=function(){
 if(state.toolId!=='risk')return rsBase.configPanel();
 const c=awConfig(),locked=!!currentTask(),a=aaView('risk');if(!locked){seedConfig('risk',c);aaPrepare(c);}
 const prompt=pgStageCard('risk','risk',c,locked).replace('配套风险点在下方勾选。','在下方选择本次要检查的风险点。');
 // Build this compact surface directly: hidden legacy lists must not allocate thousands of controls.
 return '<aside class="config ew-config aw-config tw-config aa-config pg-config rs-config" aria-label="'+(locked?'本次检查设置':'Step 3 设置风险分析内容')+'">'+(locked?'<div class="ew-panel-head"><h2>设置检查内容</h2></div>':twHeading(3,'设置风险分析内容'))+'<div class="ew-config-body"><p class="aa-config-intro">'+(locked?'本次执行时的设置，只读查看。':'选择检查风险点，已添加资料均参与核查。')+'</p>'+prompt+rsSummary(c,locked)+'<details class="aa-settings" data-aa-details="advanced" '+(a.advanced||locked?'open':'')+'><summary>检查方式</summary><select data-config="mode" aria-label="检查方式" '+(locked?'disabled':'')+'><option value="逐关注点检查各文件" '+(c.mode==='逐关注点检查各文件'?'selected':'')+'>按风险点逐项检查</option><option value="逐文件检查全部关注点" '+(c.mode==='逐文件检查全部关注点'?'selected':'')+'>按文件集中检查</option></select><p>按风险点：每次检查一个风险点。按文件：一次检查文件的全部风险点。两种方式均覆盖所选范围。</p></details>'+'</div></aside>';
};
function rsTree(p,locked){
 const groups=rsCounts(p.nodes),expanded=new Set(p.expanded),active=p.category;
 const row=(g,depth)=>{const children=groups.filter(n=>n.parent===g.path),open=expanded.has(g.path)||active.startsWith(g.path+' / ');return '<div class="rs-tree-row '+(active===g.path?'active':'')+'" style="--rs-depth:'+depth+'">'+(children.length?'<button class="rs-tree-toggle" data-action="rs-category-toggle" data-path="'+E(g.path)+'" aria-label="'+(open?'收起':'展开')+E(g.label)+'" aria-expanded="'+open+'">'+I(open?'down':'chevron','icon-sm')+'</button>':'<span class="rs-tree-spacer"></span>')+(!locked?'<input type="checkbox" data-rs-change="category" data-path="'+E(g.path)+'" aria-label="选择分类 '+E(g.path)+'（含下级）" title="勾选此分类及下级的全部风险点" '+(g.selected===g.total?'checked':'')+' '+(g.selected&&g.selected<g.total?'data-rs-mixed="true"':'')+'>':'')+'<button class="rs-category-name" data-action="rs-category" data-path="'+E(g.path)+'" title="'+E(g.path)+'"><span>'+E(g.label)+'</span><small><b>'+g.selected+'</b> / '+g.total+'</small></button></div>'+(open?children.map(c=>row(c,depth+1)).join(''):'');};
 return '<aside class="rs-categories" aria-label="风险点业务分类"><label class="rs-mobile-category"><span>业务分类</span><select data-rs-change="category-filter" aria-label="筛选业务分类"><option value="all">全部分类（已选'+rsSelected(p.nodes)+' / '+p.nodes.length+'）</option>'+groups.map(g=>'<option value="'+E(g.path)+'" '+(active===g.path?'selected':'')+'>'+E(g.path)+'（已选'+g.selected+' / '+g.total+'）</option>').join('')+'</select></label><div class="rs-category-head"><h3>业务分类</h3><span>已选 / 总数</span></div><button class="rs-category-all '+(active==='all'?'active':'')+'" data-action="rs-category" data-path="all"><span>全部分类</span><small><b>'+rsSelected(p.nodes)+'</b> / '+p.nodes.length+'</small></button><div class="rs-tree">'+groups.filter(g=>g.parent==='all').map(g=>row(g,0)).join('')+'</div>'+(!locked?'<p class="rs-tree-hint">勾选分类，包含下级全部风险点。</p>':'')+'</aside>';
}
awRiskEditor=function(raw){
 const p=rsState(raw),locked=!!currentTask(),matches=rsMatches(p),pages=Math.max(1,Math.ceil(matches.length/p.size));p.page=Math.max(1,Math.min(p.page,pages));const shown=pageItems(matches,p.page,p.size),all=shown.length&&shown.every(r=>r.node.selected),mixed=shown.some(r=>r.node.selected)&&!all;
 return modalFrame(locked?'本次检查风险点':'选择检查风险点','按业务分类勾选，可搜索风险点名称或检查说明。','<div class="rs-layout">'+rsTree(p,locked)+'<section class="rs-main"><div class="rs-topbar"><nav class="rs-tabs" aria-label="风险点范围">'+[['all','全部风险点 '+p.nodes.length],['selected','已选风险点 '+rsSelected(p.nodes)]].map(([key,label])=>B(label,'rs-view',p.view===key?'active':'','data-view="'+key+'" aria-pressed="'+(p.view===key)+'"')).join('')+'</nav>'+(!locked?B(I('plus','icon-sm')+'新增风险点','aw-risk-add','sm'):'')+'</div><div class="rs-search"><div class="search">'+I('search','icon-sm')+'<input id="rs-query" data-rs-input="query" value="'+E(p.query)+'" placeholder="搜索名称、分类或检查说明" aria-label="查找风险点"></div></div><div class="rs-scope"><span title="'+E(p.category)+'">'+E(p.category==='all'?'全部分类':p.category)+' · '+matches.length+' 个'+(p.query?'匹配项':'风险点')+'</span>'+'<div>'+(p.query||p.category!=='all'?B('清除筛选','rs-reset','ghost sm'):'')+(!locked?B('选择全部页（'+matches.length+'）','rs-select-matches','ghost sm',matches.length?'':'disabled')+B('取消当前范围选择','rs-clear-matches','ghost sm',matches.some(r=>r.node.selected)?'':'disabled'):'')+'</div>'+'</div><div class="rs-table-scroll"><table class="table rs-table"><thead><tr>'+(!locked?'<th><label><input type="checkbox" data-rs-change="page" aria-label="选择本页风险点" '+(all?'checked':'')+' '+(mixed?'data-rs-mixed="true"':'')+' '+(!shown.length?'disabled':'')+'><span>本页</span></label></th>':'')+'<th>风险点</th><th>检查说明</th><th>操作</th></tr></thead><tbody>'+shown.map(({node:r,index})=>'<tr class="'+(r.selected?'rs-selected':'')+'">'+(!locked?'<td><input type="checkbox" id="rs-point-'+index+'" data-rs-change="node" data-index="'+index+'" aria-label="选择 '+E(r.name)+'" '+(r.selected?'checked':'')+'></td>':'')+'<td><label class="rs-point-name" '+(!locked?'for="rs-point-'+index+'"':'')+'>'+E(r.name)+'</label><small class="rs-point-category" title="'+E(r.path)+'">'+E(rsCategory(r))+'</small></td><td><p class="rs-description" title="'+E(r.description)+'">'+E(r.description)+'</p></td><td>'+A(locked?'详情':'编辑','rs-point-edit','data-index="'+index+'"')+'</td></tr>').join('')+(!shown.length?'<tr><td colspan="'+(locked?3:4)+'"><div class="rs-empty">'+(p.query?'没有匹配的风险点，试试其他关键词。':p.view==='selected'?'当前范围尚未选择风险点。':'当前分类没有风险点。')+(p.query||p.category!=='all'?B('清除筛选','rs-reset','ghost sm'):'')+'</div></td></tr>':'')+'</tbody></table></div><footer class="rs-pagination"><span>共 <strong>'+matches.length+'</strong> 个</span><div><label>每页 <select data-rs-change="size" aria-label="风险点每页条数">'+[20,50,100].map(n=>'<option value="'+n+'" '+(p.size===n?'selected':'')+'>'+n+'</option>').join('')+'</select></label>'+B('上一页','rs-page','sm','data-step="-1" '+(p.page<=1?'disabled':''))+'<span>第 '+p.page+' / '+pages+' 页</span>'+B('下一页','rs-page','sm','data-step="1" '+(p.page>=pages?'disabled':''))+'</div></footer></section></div><p id="aw-risk-editor-error" class="error rs-error" role="alert">'+E(p.error)+'</p>','<span class="rs-footer-count">'+(locked?'本次检查':'已选')+' <strong>'+rsSelected(p.nodes)+'</strong> 个风险点</span>'+B(locked?'关闭':'取消','close-modal')+(!locked?B('确认选择','aw-risk-save','primary'):''),'rs-dialog');
};
function rsEditModal(p){const locked=!!currentTask(),r=p.draft;return modalFrame(locked?'风险点详情':p.index<0?'新增风险点':'编辑风险点',locked?'本次执行时使用的检查说明，只读查看。':'修改先保留在清单草稿中，确认选择后用于本次核查。','<label class="field"><span>风险点名称 <b class="red">*</b></span><input id="rs-name" data-rs-edit="name" value="'+E(r.name)+'" maxlength="200" '+(locked?'readonly':'')+'></label><label class="field"><span>业务分类 <b class="red">*</b></span><input id="rs-path" data-rs-edit="path" value="'+E(r.path)+'" placeholder="例如：资金管理 / 支付审批" maxlength="500" '+(locked?'readonly':'')+'><small class="hint">多级分类用“ / ”分隔。</small></label><label class="field"><span>检查说明 <b class="red">*</b></span><textarea id="rs-description" data-rs-edit="description" rows="6" placeholder="说明需核查的业务事项、依据和异常情形。" '+(locked?'readonly':'')+'>'+E(r.description)+'</textarea></label><p id="rs-edit-error" class="error" role="alert">'+E(p.error||'')+'</p>',(!locked&&p.index>=0?B('删除风险点','rs-point-delete','ghost danger rs-delete'):'')+B(locked?'返回':'取消','close-modal')+(!locked?B('保存','rs-point-save','primary'):''),'rs-edit-dialog medium');}
function rsPaint(focusId,resetTable=false){const listTop=resetTable?0:document.querySelector('.rs-table-scroll')?.scrollTop||0,categories=document.querySelector('.rs-tree')?.scrollTop||0,focused=document.activeElement,focusData=focused?.closest('.rs-dialog')?{...focused.dataset}:null;paintModal();const tree=document.querySelector('.rs-tree');if(tree)tree.scrollTop=categories;const list=document.querySelector('.rs-table-scroll');if(list)list.scrollTop=listTop;document.querySelectorAll('[data-rs-mixed]').forEach(el=>el.indeterminate=true);if(focusId)document.getElementById(focusId)?.focus();else if(focusData&&(focusData.action||focusData.rsChange)){const selector=focusData.action?'[data-action]':'[data-rs-change]';[...document.querySelectorAll('.rs-dialog '+selector)].find(el=>Object.entries(focusData).filter(([key])=>key!=='rsMixed').every(([key,value])=>el.dataset[key]===value))?.focus();}}
modalContent=function(){if(modal==='rs-point-edit')return rsEditModal(modalData);if(modal==='rs-point-delete-confirm')return modalFrame('删除此风险点？','','<p>“'+E(modalData.back.draft.name)+'”将从本次风险点清单中移除，提示词库和历史记录保留。</p>',B('取消','close-modal')+B('删除','rs-point-delete-confirm','danger'),'small');return rsBase.modalContent();};
closeModal=function(){if(modal==='rs-point-edit'){const parent=modalData.back;openModal('aw-risk-editor',parent);rsPaint();return;}if(modal==='rs-point-delete-confirm'){openModal('rs-point-edit',modalData.back);return;}return rsBase.closeModal();};
handleAction=function(action,el){
 if(state.toolId!=='risk')return rsBase.handleAction(action,el);
 if(action==='aw-risk-editor'){const c=awConfig(),checked=new Set(c.checks),nodes=structuredClone(c.riskNodes).map(n=>({...n,selected:checked.has(n.name)}));openModal('aw-risk-editor',{nodes,initial:JSON.stringify(nodes)});rsPaint();return;}
 if(modal==='aw-risk-editor'){
  const p=rsState(modalData),locked=!!currentTask();
  if(action==='rs-category-toggle'){p.expanded=p.expanded.includes(el.dataset.path)?p.expanded.filter(v=>v!==el.dataset.path):[...p.expanded,el.dataset.path];rsPaint();return;}
  if(action==='rs-category'){p.category=el.dataset.path;p.page=1;rsPaint(null,true);return;}
  if(action==='rs-view'){p.view=el.dataset.view;p.query='';p.category='all';p.page=1;rsPaint(null,true);return;}
  if(action==='rs-reset'){p.query='';p.category='all';p.page=1;rsPaint(null,true);return;}
  if(action==='rs-page'){p.page+=+el.dataset.step;rsPaint(null,true);return;}
  if(['rs-select-matches','rs-clear-matches'].includes(action)&&!locked){for(const {node} of rsMatches(p))node.selected=action==='rs-select-matches';p.error='';rsPaint();return;}
  if(action==='aw-risk-add'&&!locked||action==='rs-point-edit'){const index=action==='aw-risk-add'?-1:+el.dataset.index,draft=index<0?{id:'rp-'+crypto.randomUUID(),name:'',path:p.category==='all'?'自定义风险点':p.category,description:'',selected:true}:structuredClone(p.nodes[index]);if(!draft)return;openModal('rs-point-edit',{index,draft,back:structuredClone(p),error:''});if(!locked)document.getElementById('rs-name')?.focus();return;}
  if(action==='aw-risk-save'&&!locked){const out=rsBase.handleAction(action,el);if(modal==='aw-risk-editor'){const error=document.getElementById('aw-risk-editor-error')?.textContent;modalData.error=error||'';}return out;}
 }
 if(modal==='rs-point-edit'&&!currentTask()){
  const p=modalData;
  if(action==='rs-point-delete'){openModal('rs-point-delete-confirm',{back:structuredClone(p)});return;}
  if(action==='rs-point-save'){const r={...p.draft,name:p.draft.name.trim(),path:p.draft.path.trim(),description:p.draft.description.trim()};const error=!r.name||!r.path||!r.description?'请填写风险点名称、业务分类和检查说明。':p.back.nodes.some((n,i)=>i!==p.index&&n.name.trim()===r.name)?'风险点名称已存在，请使用不同名称。':'';if(error){p.error=error;document.getElementById('rs-edit-error').textContent=error;return;}const parent=p.back;if(p.index<0)parent.nodes.push(r);else parent.nodes[p.index]=r;parent.category=rsCategory(r);parent.query='';parent.view='all';parent.page=1;parent.expanded=rsCategory(r).split(' / ').map((_,i)=>rsCategory(r).split(' / ').slice(0,i+1).join(' / '));parent.error='';const target=p.index<0?parent.nodes.length-1:p.index;parent.page=Math.floor(rsMatches(parent).findIndex(n=>n.index===target)/parent.size)+1;openModal('aw-risk-editor',parent);rsPaint(null,true);return;}
 }
 if(action==='rs-point-delete-confirm'&&modal==='rs-point-delete-confirm'&&!currentTask()){const edit=modalData.back,parent=edit.back;parent.nodes.splice(edit.index,1);parent.error='';openModal('aw-risk-editor',parent);rsPaint();return;}
 return rsBase.handleAction(action,el);
};
window.addEventListener('input',e=>{
 const el=e.target;if(state.toolId!=='risk')return;
 if(modal==='rs-point-edit'&&el.dataset.rsEdit&&!currentTask()){e.stopImmediatePropagation();modalData.draft[el.dataset.rsEdit]=el.value;return;}
 if(modal!=='aw-risk-editor'||el.dataset.rsInput!=='query')return;e.stopImmediatePropagation();const start=el.selectionStart,end=el.selectionEnd;modalData.query=el.value;modalData.page=1;rsPaint('rs-query',true);document.getElementById('rs-query')?.setSelectionRange(start,end);
},true);
window.addEventListener('change',e=>{
 const el=e.target,key=el.dataset.rsChange;if(state.toolId!=='risk'||modal!=='aw-risk-editor'||!key)return;e.stopImmediatePropagation();const p=rsState(modalData);if(key==='size'){p.size=+el.value;p.page=1;rsPaint(null,true);return;}if(key==='category-filter'){p.category=el.value;p.page=1;rsPaint(null,true);return;}if(currentTask())return;
 const nodes=key==='node'?[p.nodes[+el.dataset.index]]:key==='page'?pageItems(rsMatches(p),p.page,p.size).map(r=>r.node):key==='category'?p.nodes.filter(n=>rsWithin(n,el.dataset.path)):[];for(const node of nodes)if(node)node.selected=el.checked;p.error='';rsPaint();
},true);
render();
